#include <bits/stdc++.h>
using namespace std;

int encode(const vector<int>& array, int length) {
    int result = 0;
    for (int j = 0; j < length; j++) {
        result = result * 3 + array[j];
    }
    return result;
}

void decode(vector<int>& array, int length, int code, int base) {
    for (int j = length - 1; j >= 0; j--) {
        array[j] = code % base;
        code /= base;
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    if (n < m) {
        int temp = n; n = m; m = temp;
    }
    int p = 1;
    for (int j = 0; j < m; j++) p *= 3;
    vector<int> dp(p, -1);
    vector<int> dq(p, -1);
    vector<int> aa(m, 1);
    vector<int> bb(m);
    dp[encode(aa, m)] = 0;
    while (n-- > 0) {
        std::fill(dq.begin(), dq.end(), -1);
        for (int a = 0; a < p; a++) {
            if (dp[a] < 0) continue;
            vector<int> temp_aa = aa;
            decode(temp_aa, m, a, 3);
            for (int b = 0; b < (1 << m); b++) {
                vector<int> temp_bb = bb;
                decode(temp_bb, m, b, 2);
                bool invalid = false;
                for (int j = 0; j < m; j++) {
                    if (temp_aa[j] == 0 && temp_bb[j] == 0) {
                        invalid = true;
                        break;
                    }
                }
                if (invalid) continue;
                int count = 0;
                for (int j = 0; j < m; j++) {
                    if (temp_bb[j] == 1) {
                        temp_bb[j] = 2;
                        count++;
                    }
                }
                for (int j = 0; j < m; j++) {
                    if (temp_bb[j] == 0 && (temp_aa[j] == 2 || (j > 0 && temp_bb[j - 1] == 2) || (j + 1 < m && temp_bb[j + 1] == 2))) {
                        temp_bb[j] = 1;
                    }
                }
                int newA = encode(temp_bb, m);
                dq[newA] = max(dq[newA], dp[a] + m - count);
            }
        }
        swap(dp, dq);
    }
    int answer = 0;
    for (int a = 0; a < p; a++) {
        if (dp[a] <= answer) continue;
        vector<int> temp_aa = aa;
        decode(temp_aa, m, a, 3);
        bool bad = false;
        for (int j = 0; j < m; j++) {
            if (temp_aa[j] == 0) {
                bad = true;
                break;
            }
        }
        if (!bad) answer = dp[a];
    }
    cout << answer << "\n";
    return 0;
}
